import React, { useState } from "react";
import emailjs from "emailjs-com";

import "./contactStyle.css";

const recipientEmail = "patelkuldeep0001@gmail.com";

function Contact() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [isSending, setIsSending] = useState(false);
  const [status, setStatus] = useState("");
  const [fallbackLink, setFallbackLink] = useState("");

  const sendEmail = (e) => {
    e.preventDefault();
    setIsSending(true);
    setStatus("");
    setFallbackLink("");

    emailjs.sendForm(
      "service_eqp4gzb",
      "template_fksqbf6",
      e.currentTarget,
      "user_cYxQj4CXBNqFVuIqfsndF"
    ).then(() => {
      setStatus("Message sent successfully.");
      setName("");
      setEmail("");
      setSubject("");
      setMessage("");
      e.currentTarget.reset();
    }).catch(() => {
      const formData = new FormData(e.currentTarget);
      const subjectLine = formData.get("subject") || "Portfolio contact";
      const body = `Name: ${formData.get("name")}\nEmail: ${formData.get("email")}\n\n${formData.get("message")}`;
      setFallbackLink(`mailto:${recipientEmail}?subject=${encodeURIComponent(subjectLine)}&body=${encodeURIComponent(body)}`);
      setStatus("The online sender is temporarily unavailable. You can open your email app and send this message directly.");
    }).finally(() => {
      setIsSending(false);
    });
  }

  return (
    <>
      <div className='contact'>
        <h1>Contact</h1>
        <form onSubmit={sendEmail}>
          <div className='form-input'>
            <label>Full Name :</label>
            <input
              type='text'
              placeholder='Enter Your Name'
              value={name}
              onChange={(e) => setName(e.target.value)}
              name='name'
              id='name'
              required
            />
          </div>

          <div className='form-input'>
            <label>Email-Address :</label>
            <input
              type='email'
              placeholder='Enter Your Email-Address'
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              name='email'
              id='email'
              required
            />
          </div>
          <div className='form-input'>
            <label>Subject :</label>
            <input
              type='text'
              placeholder='Enter Message Subject'
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              name='subject'
            />
          </div>
          <div className='form-input'>
            <label>Message :</label>
            <textarea
              type='text'
              placeholder='Enter Your Message'
              rows='4'
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              name='message'
              required
            ></textarea>
          </div>
          <button className='form-input' type='submit' disabled={isSending}>
            {isSending ? 'Sending...' : 'Send message'}
          </button>
          {status && <p className="form-status" role="status">{status}</p>}
          {fallbackLink && <a className="form-fallback" href={fallbackLink}>Open email app</a>}
        </form>
      </div>
    </>
  );
}

export default Contact;
